def busqueda_binaria(numeros, objetivo):
    izquierda, derecha = 0, len(numeros) - 1
    while izquierda <= derecha:
        medio = (izquierda + derecha) // 2
        if numeros[medio] == objetivo:
            return medio
        if numeros[medio] < objetivo:
            izquierda = medio + 1
        else:
            derecha = medio - 1
    return -1

print(busqueda_binaria([1, 3, 5, 7, 9], 7))

def burbuja(lista):
    copia = lista.copy()
    for fin in range(len(copia) - 1, 0, -1):
        for i in range(fin):
            if copia[i] > copia[i + 1]:
                copia[i], copia[i + 1] = copia[i + 1], copia[i]
    return copia

print(burbuja([9, 2, 5, 1]))

from math import isqrt

def es_primo(n):
    if n < 2:
        return False
    for divisor in range(2, isqrt(n) + 1):
        if n % divisor == 0:
            return False
    return True

print(es_primo(29))

